// The board chrome: the neutral interface around the specimens (toolbar, view tabs, card frames, labels).
// Source: design-build/chrome/chrome.tokens.json (DTCG, light and dark) and the font files in design-build/chrome/fonts.
// Output: design-build/preview/chrome.css, generated by board.mjs and listed in lint.config.json generated_files.
// The chrome never takes the brand: brand tokens (tokens/tokens.json) style only what sits inside a specimen.
// Its scheme follows the brand theme in force (:root[data-theme] → light or dark by name, else the OS), so a
// dark board is dark everywhere. lint.mjs rule chrome-tokens checks the pairings listed in the file.
import fs from 'node:fs';
import path from 'node:path';
import { loadTokens, flatten, varName, toCss, resolveValue } from './tokens.mjs';
import { contrastRatio } from './color.mjs';

export const CHROME_DIR = 'design-build/chrome';
export const CHROME_TOKENS = `${CHROME_DIR}/chrome.tokens.json`;
export const CHROME_CSS = 'design-build/preview/chrome.css';
export const CHROME_EXT = 'org.design-system.chrome';
export const schemeOf = (theme) => (/(^|-)dark($|-)/.test(theme) ? 'dark' : 'light');

export function loadChrome(root) {
  const loaded = loadTokens(path.join(root, CHROME_TOKENS));
  const ext = loaded.json?.$extensions?.[CHROME_EXT] || {};
  return { loaded, ext, flat: loaded.problems.length ? new Map() : flatten(loaded) };
}

/** The --chrome-* custom property names the file defines (lint accepts these in board files only). */
export function chromeVarNames(root) {
  const { loaded } = loadChrome(root);
  return new Set([...loaded.tokens.values()].flatMap((t) => (t.type === 'typography' ? [varName(t.path), `${varName(t.path)}-tracking`] : [varName(t.path)])));
}

function decls(c, mode) {
  const out = [];
  for (const t of c.loaded.tokens.values()) {
    if (t.type === 'typography') {
      const v = resolveValue(c.loaded.tokens, t.path, mode);
      out.push([varName(t.path), toCss('typography', v)]);
      if (v?.letterSpacing !== undefined) out.push([`${varName(t.path)}-tracking`, toCss('dimension', v.letterSpacing)]);
      continue;
    }
    const css = c.flat.get(t.path)?.css || {};
    out.push([varName(t.path), css[mode] ?? css.base]);
  }
  return out;
}

/** chrome.css text. themes: the brand theme names (design.md themes:), first = default. */
export function buildChromeCss(root, themes = ['light', 'dark']) {
  const c = loadChrome(root);
  if (c.loaded.problems.length) return `/* ${CHROME_TOKENS} has problems: run node design-build/lint.mjs (rule chrome-tokens) */\n`;
  const light = decls(c, 'light'), dark = decls(c, 'dark');
  const diff = dark.filter(([n, v], i) => v !== light[i][1]);
  const block = (sel, ds, ind = '') => `${ind}${sel} {\n${ds.map(([n, v]) => `${ind}  ${n}: ${v};`).join('\n')}\n${ind}}`;
  const def = schemeOf(themes[0] || 'light');
  const rel = path.relative(path.join(root, path.dirname(CHROME_CSS)), path.join(root, CHROME_DIR, 'fonts')).split(path.sep).join('/');
  const out = [`/* GENERATED from ${CHROME_TOKENS} by design-build/board.mjs. Do not edit: change the chrome tokens and re-run. */`,
    `/* Board chrome only (toolbar, tabs, card frames, labels). Specimens use the brand tokens in tokens.css. */`];
  for (const f of c.ext.faces || []) {
    out.push(`@font-face {\n  font-family: "${f.family}";\n  src: url("${rel}/${f.file}") format("woff2");\n  font-weight: ${f.weight};\n  font-style: normal;\n  font-display: block;\n  unicode-range: ${f.unicodeRange || c.ext.unicodeRange || 'U+0000-00FF'};\n}`);
  }
  out.push(block(':root', def === 'dark' ? [...light.filter(([n], i) => !diff.some(([m]) => m === n)), ...diff] : light));
  if (def === 'light' && themes.some((t) => schemeOf(t) === 'dark')) out.push(`@media (prefers-color-scheme: dark) {\n${block(':root:not([data-theme])', diff, '  ')}\n}`);
  // Dark-first: the default chrome is dark. A light theme in the list follows the OS, same as dark does for a light default.
  if (def === 'dark' && themes.some((t) => schemeOf(t) === 'light')) out.push(`@media (prefers-color-scheme: light) {\n${block(':root:not([data-theme])', light.filter(([n]) => diff.some(([m]) => m === n)), '  ')}\n}`);
  for (const th of themes) out.push(block(`:root[data-theme="${th}"]`, schemeOf(th) === 'dark' ? diff : light.filter(([n]) => diff.some(([m]) => m === n))));
  // a pane that shows one theme next to another (Compare, the studies page) sets data-chrome="<light|dark>"
  out.push(block('[data-chrome="light"]', light.filter(([n]) => diff.some(([m]) => m === n))), block('[data-chrome="dark"]', diff));
  return out.join('\n') + '\n';
}

/** Problems for lint rule chrome-tokens: DTCG errors, missing font files, pairings under their minimum. */
export function checkChrome(root) {
  const c = loadChrome(root), problems = [];
  const file = CHROME_TOKENS;
  if (!fs.existsSync(path.join(root, file))) return [];
  for (const p of c.loaded.problems) problems.push({ file, line: p.line, message: p.message, fix: p.fix });
  if (c.loaded.problems.length) return problems;
  const lineOf = (needle) => { const i = c.loaded.text.indexOf(needle); return i < 0 ? 1 : c.loaded.text.slice(0, i).split('\n').length; };
  for (const f of c.ext.faces || []) {
    if (!fs.existsSync(path.join(root, CHROME_DIR, 'fonts', f.file))) problems.push({ file, line: lineOf(f.file), message: `chrome font file ${CHROME_DIR}/fonts/${f.file} is missing`, fix: 'add the woff2 (and its license) or remove the face' });
  }
  const families = new Set((c.ext.faces || []).map((f) => f.family));
  for (const p of ['chrome.font.ui', 'chrome.font.mono']) {
    const fam = c.flat.get(p)?.families?.[0];
    if (fam && !families.has(fam)) problems.push({ file, line: c.loaded.tokens.get(p)?.line || 1, message: `${p} starts with "${fam}", which no shipped face provides`, fix: 'ship the font in design-build/chrome/fonts and list it under faces' });
  }
  for (const pair of c.ext.pairings || []) {
    for (const bg of [].concat(pair.bg)) {
      for (const mode of ['light', 'dark']) {
        const fc = c.flat.get(pair.fg)?.color, bc = c.flat.get(bg)?.color;
        const f = fc?.[mode] ?? fc?.base, b = bc?.[mode] ?? bc?.base;
        if (!f || !b) { problems.push({ file, line: lineOf(`"${pair.fg}"`), message: `pairing ${pair.fg} on ${bg}: token missing`, fix: 'point the pairing at existing chrome tokens' }); continue; }
        const r = contrastRatio(f, b);
        if (r + 1e-9 < pair.min) problems.push({ file, line: c.loaded.tokens.get(pair.fg)?.line || lineOf(`"${pair.fg}"`), message: `${pair.fg} on ${bg} is ${r.toFixed(2)}:1 in ${mode}, under ${pair.min}:1`, fix: `darken or lighten ${pair.fg} in ${mode}` });
      }
    }
  }
  return problems;
}
